DELETE FROM AD_FieldCustom_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_FieldCustom fc ON(fc.AD_Field_ID = f.AD_Field_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND fc.AD_FieldCustom_ID = AD_FieldCustom_Trl.AD_FieldCustom_ID);
DELETE FROM AD_FieldCustom WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND f.AD_Field_ID = AD_FieldCustom.AD_Field_ID);
DELETE FROM AD_Field WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND c.AD_Column_ID = AD_Field.AD_Column_ID);
DELETE FROM AD_Browse_Field_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_Browse_Field bf ON(bf.AD_View_Column_ID = vc.AD_View_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND bf.AD_Browse_Field_ID = AD_Browse_Field_Trl.AD_Browse_Field_ID);
DELETE FROM AD_Browse_Field WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND vc.AD_View_Column_ID = AD_Browse_Field.AD_View_Column_ID);
DELETE FROM AD_View_Column_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND vc.AD_View_Column_ID = AD_View_Column_Trl.AD_View_Column_ID);
DELETE FROM AD_View_Column WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName = 'C_Order') AND c.AD_Column_ID >= 1000000 AND c.ColumnName IN('IsRecognized') AND c.AD_Column_ID = AD_View_Column.AD_Column_ID);
DELETE FROM AD_Column WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = AD_Column.AD_Table_ID AND t.TableName = 'C_Order') AND AD_Column_ID >= 1000000 AND ColumnName IN('IsRecognized');
DELETE FROM AD_Element WHERE AD_Element_ID >= 1000000 AND ColumnName IN('IsRecognized');

DELETE FROM AD_FieldCustom_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_FieldCustom fc ON(fc.AD_Field_ID = f.AD_Field_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND fc.AD_FieldCustom_ID = AD_FieldCustom_Trl.AD_FieldCustom_ID);
DELETE FROM AD_FieldCustom WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_Field f ON(f.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND f.AD_Field_ID = AD_FieldCustom.AD_Field_ID);
DELETE FROM AD_Field WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND c.AD_Column_ID = AD_Field.AD_Column_ID);
DELETE FROM AD_Browse_Field_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) INNER JOIN AD_Browse_Field bf ON(bf.AD_View_Column_ID = vc.AD_View_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND bf.AD_Browse_Field_ID = AD_Browse_Field_Trl.AD_Browse_Field_ID);
DELETE FROM AD_Browse_Field WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND vc.AD_View_Column_ID = AD_Browse_Field.AD_View_Column_ID);
DELETE FROM AD_View_Column_Trl WHERE EXISTS(SELECT 1 FROM AD_Column c INNER JOIN AD_View_Column vc ON(vc.AD_Column_ID = c.AD_Column_ID) WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND vc.AD_View_Column_ID = AD_View_Column_Trl.AD_View_Column_ID);
DELETE FROM AD_View_Column WHERE EXISTS(SELECT 1 FROM AD_Column c WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = c.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND c.AD_Column_ID >= 1000000 AND c.AD_Column_ID = AD_View_Column.AD_Column_ID);
UPDATE AD_Tab SET AD_Column_ID = null WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = AD_Tab.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND AD_Column_ID >= 1000000;
DELETE FROM AD_Column WHERE EXISTS(SELECT 1 FROM AD_Table t WHERE t.AD_Table_ID = AD_Column.AD_Table_ID AND t.TableName IN('C_RevenueRecognition_Run', 'C_RevenueRecognition', 'C_RevenueRecognition_Plan')) AND AD_Column_ID >= 1000000;
